def _rollback(target_real: str, directory: str, backup_path: str | None,
              first: BaseException) -> None:
    # Restore the bytes the target held when the copy started, while the
    # target lock is still held exclusively. When a backup exists it is
    # moved back over the target atomically, which restores the old bytes
    # and removes the backup temp in one rename; otherwise the target this
    # call created is removed.
    try:
        if backup_path is not None:
            os.replace(backup_path, target_real)
        else:
            try:
                os.unlink(target_real)
            except FileNotFoundError:
                pass
        _fsync_dir_plain(directory)
    except OSError as rollback:
        # A replace that failed leaves the backup holding the old bytes in
        # the target's directory; leave it (and the first error) intact so
        # the caller can finish the recovery by hand.
        raise rollback from first

